	/* @Before */
	public void setUp()
    {

		// turn off debug and info log statements that make the console noisy
		setLogLevel(typeof(GhidraScript), Level.ERROR);
		setLogLevel(typeof(ScriptTaskListener), Level.ERROR);

		env = new TestEnv();
		ToyProgramBuilder builder = new ToyProgramBuilder("sample", true);
		program = builder.getProgram();
		tool = env.launchDefaultTool(program);

		plugin = env.getPlugin(typeof(ConsolePlugin));
		provider = (ConsoleComponentProvider) tool.getComponentProvider("Console");
		textPane = provider.getTextPane();

		ResourceFile resourceFile =
			Application.getModuleFile("Base", "ghidra_scripts/HelloWorldScript.java");
		File scriptFile = resourceFile.getFile(true);
		env.runScript(scriptFile);

		AnimationUtils.setAnimationEnabled(false);

		placeCursorAtBeginning();
		findDialog = showFindDialog();
	}

	/* @After */
	public void tearDown() {
		close(findDialog);
		env.dispose();
	}

	/* @Test */
	public void testFindAll()
    {

		string searchText = "Hello";
		findAll(searchText);
		assertFalse(findDialog.isShowing());
		List<TestTextMatch> matches = getExpectedMatches(searchText);
		assertEquals(3, matches.size());

		verfiyHighlightColor(matches);

		FindDialogResultsProvider resultsProvider =
			waitForComponentProvider(typeof(FindDialogResultsProvider));
		List<SearchLocation> results = resultsProvider.getResults();
		assertEquals(matches.size(), results.size());

		int row = 0;
		selectRow(resultsProvider, row);
		assertActiveHighlight(matches.get(row));
		assertCursorInMatch(matches.get(row));

		row = 1;
		selectRow(resultsProvider, row);
		assertActiveHighlight(matches.get(row));
		assertCursorInMatch(matches.get(row));

		row = 2;
		selectRow(resultsProvider, row);
		assertActiveHighlight(matches.get(row));
		assertCursorInMatch(matches.get(row));
	}

